Idea:
- Let v_p(n) be the exponent of prime p in n.
- For each prime p, let e_i = v_p(T_i). Then g(T_i/T_{i+1}) = B_i implies v_p(B_i) = |e_i − e_{i+1}|.
- The gcd(T_1,…,T_M) = 1 means for every prime p, min_i e_i = 0 (at least one e_i is 0).
- Weight(T) = ∏_p p^{∑_i e_i(p)}. So the total sum of weights factors over primes:
  Answer = ∏_p S_p, where S_p is the sum over all sequences (e_1,…,e_M)≥0 with |e_i−e_{i+1}|=d_i (d_i=v_p(B_i)) and min_i e_i=0, of p^{∑ e_i}.

Key DP for a fixed prime p:
- Let d_1,…,d_{M−1} be the v_p(B_i), and S = ∑ d_i. For sequences with min 0, all e_i lie in [0,S].
- We compute S_p directly by dynamic programming over e_i in [0,S] while enforcing “at least one zero appears”.

DP details:
- Precompute pow[k] = p^k mod MOD for k=0..S.
- dp0[x]: sum of weights for sequences up to current index with e=current=x and no zero seen yet.
- dp1[x]: same but at least one zero has been seen.
- Initialization (i=1):
  - dp1[0] = 1 (weight includes p^{e_1}=p^0).
  - For x=1..S: dp0[x] = pow[x].
- Transition for step i (from e_i to e_{i+1}), with d = d_i:
  - If d=0: only y=x is allowed.
  - If d>0: y can be x+d (if ≤S) and, if x≥d, also y=x−d.
  - Multiply by pow[y] (for the weight of e_{i+1}), and update dp0/dp1. If y==0 and coming from dp0, set the “seen zero” flag (go to dp1).
- After processing all M−1 steps, S_p = sum_x dp1[x] mod MOD.

Overall algorithm:
- Factor each B_i (B_i ≤ 1000) to collect d_i=v_p(B_i) for each prime p appearing in any B_i.
- For each such prime p, run the DP above to get S_p (if all d_i=0, S_p=1).
- Multiply all S_p modulo 998244353.

Complexity:
- For a prime p, DP time is O(M · S) with S=∑ v_p(B_i). Summed over all primes, this is O(M · ∑_i Ω(B_i)), which is ≤ about 9·10^6 operations for given constraints, well within limits.

Reference implementation (C++17):

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M;
    if (!(cin >> M)) return 0;
    vector<int> B(M-1);
    for (int i = 0; i < M-1; ++i) cin >> B[i];

    // Sieve primes up to 1000
    const int LIM = 1000;
    vector<int> primes;
    vector<bool> is_composite(LIM+1,false);
    for (int i = 2; i <= LIM; ++i) {
        if (!is_composite[i]) {
            primes.push_back(i);
            if ((long long)i*i <= LIM) {
                for (int j = i*i; j <= LIM; j += i) is_composite[j] = true;
            }
        }
    }

    // Map prime -> vector of d_i = v_p(B_i)
    unordered_map<int, vector<int>> dmap;
    dmap.reserve(256);
    for (int i = 0; i < M-1; ++i) {
        int n = B[i];
        int x = n;
        for (int p : primes) {
            if ((long long)p*p > x) break;
            if (x % p == 0) {
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    ++cnt;
                }
                auto &vec = dmap[p];
                if (vec.empty()) vec.assign(M-1, 0);
                vec[i] = cnt;
            }
        }
        if (x > 1) {
            int p = x; // leftover prime
            auto &vec = dmap[p];
            if (vec.empty()) vec.assign(M-1, 0);
            vec[i] += 1;
        }
    }

    long long ans = 1;

    for (auto &kv : dmap) {
        int p = kv.first;
        const vector<int> &d = kv.second;
        int S = 0;
        for (int v : d) S += v;
        if (S == 0) {
            // All |e_i - e_{i+1}| = 0 => constant sequence; min=0 => all zeros; contributes 1
            ans = (ans * 1) % MOD;
            continue;
        }
        vector<long long> powp(S+1, 1);
        for (int k = 1; k <= S; ++k) powp[k] = (powp[k-1] * p) % MOD;

        vector<long long> dp0(S+1, 0), dp1(S+1, 0);
        dp1[0] = 1; // e1=0
        for (int x = 1; x <= S; ++x) dp0[x] = powp[x]; // e1=x>0

        for (int i = 0; i < M-1; ++i) {
            int di = d[i];
            vector<long long> ndp0(S+1, 0), ndp1(S+1, 0);
            for (int x = 0; x <= S; ++x) {
                long long a0 = dp0[x], a1 = dp1[x];
                if (a0 == 0 && a1 == 0) continue;
                if (di == 0) {
                    int y = x;
                    long long w = powp[y];
                    if (a0) {
                        if (y == 0) {
                            ndp1[y] = (ndp1[y] + a0 * w) % MOD;
                        } else {
                            ndp0[y] = (ndp0[y] + a0 * w) % MOD;
                        }
                    }
                    if (a1) {
                        ndp1[y] = (ndp1[y] + a1 * w) % MOD;
                    }
                } else {
                    int y1 = x + di;
                    if (y1 <= S) {
                        long long w1 = powp[y1];
                        if (a0) {
                            // y1 > 0 since di>0
                            ndp0[y1] = (ndp0[y1] + a0 * w1) % MOD;
                        }
                        if (a1) {
                            ndp1[y1] = (ndp1[y1] + a1 * w1) % MOD;
                        }
                    }
                    if (x >= di) {
                        int y2 = x - di;
                        long long w2 = powp[y2];
                        if (a0) {
                            if (y2 == 0) {
                                ndp1[y2] = (ndp1[y2] + a0 * w2) % MOD;
                            } else {
                                ndp0[y2] = (ndp0[y2] + a0 * w2) % MOD;
                            }
                        }
                        if (a1) {
                            ndp1[y2] = (ndp1[y2] + a1 * w2) % MOD;
                        }
                    }
                }
            }
            dp0.swap(ndp0);
            dp1.swap(ndp1);
        }

        long long Sp = 0;
        for (int x = 0; x <= S; ++x) {
            Sp += dp1[x];
            if (Sp >= MOD) Sp -= MOD;
        }
        ans = (ans * (Sp % MOD)) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

This computes the required sum of weights modulo 998244353 in O(M · ∑_i Ω(B_i)) time.

