def solve():
    MOD = 998244353
    M = int(input())
    T = input().strip()

    def is_balanced(s):
        """Check if a string is a balanced bracket word"""
        if len(s) == 0:
            return True
        if len(s) % 2 == 1:
            return False

        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    def flip(s):
        """Flip a balanced bracket string (reverse and swap brackets)"""
        reversed_s = s[::-1]
        result = []
        for c in reversed_s:
            if c == '(':
                result.append(')')
            else:
                result.append('(')
        return ''.join(result)

    def get_all_balanced_substrings(s):
        """Find all contiguous balanced bracket substrings and their positions"""
        substrings = []
        n = len(s)

        for i in range(n):
            balance = 0
            for j in range(i, n):
                if s[j] == '(':
                    balance += 1
                else:
                    balance -= 1

                if balance < 0:
                    break

                if balance == 0 and j > i:  # Non-empty balanced substring
                    substrings.append((i, j + 1))  # Store as (start, end)
                elif balance == 0 and j == i:  # Single balanced substring
                    if is_balanced(s[i:j+1]):
                        substrings.append((i, j + 1))

        return substrings

    visited = set()
    queue = [T]
    visited.add(T)

    while queue:
        current = queue.pop(0)

        # Find all balanced substrings
        balanced_ranges = get_all_balanced_substrings(current)

        for start, end in balanced_ranges:
            substring = current[start:end]
            if is_balanced(substring) and len(substring) > 0:
                # Apply flip
                flipped = flip(substring)
                new_string = current[:start] + flipped + current[end:]

                if new_string not in visited:
                    visited.add(new_string)
                    queue.append(new_string)

    print(len(visited) % MOD)

